(* [comment removed for export] *)
Lemma primary_class_facts : forall n, 0 <= n -> is_primary n = true ->
  let c := class_id (needed_size n) in
  1 <= c <= 30 /\ needed_size n <= size_of_class c /\ 32 <= size_of_class c <= 65536
