Definition remap_node {R} (pb l : Z) (k : AM R) : AM R :=
  SVis (AMmap pb l PROT_RW F_FIXNORES)
       (fun r => if r =? pb then k else if is_err r then aundef_ USpin k else aundef_ UBadAnswer k).

