Definition batches_cost (bs : list abatch) : nat :=
  fold_right (fun b acc => (4 * length (b_chunks b) + 3 + acc)%nat) 0%nat bs.

Lemma do_recycle_depth : forall R bs st (k : astate -> AM R) n,
